import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{C as r,c as a,o as s,ag as d,G as n}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const P=JSON.parse('{"title":"dot：ChatGPT 里的常驻智能体","description":"dot 是 ChatGPT 里的常驻智能体：给它目标和上下文，关掉标签页它也在自己的云电脑上接着干。本页讲清你能不能用、怎么创建、怎么派活、怎么管住它，以及它和 Codex 怎么分工。","frontmatter":{"title":"dot：ChatGPT 里的常驻智能体","description":"dot 是 ChatGPT 里的常驻智能体：给它目标和上下文，关掉标签页它也在自己的云电脑上接着干。本页讲清你能不能用、怎么创建、怎么派活、怎么管住它，以及它和 Codex 怎么分工。","domain":"product","tags":["coding-agent","chatgpt-dot","always-on-agent"],"role":"tutorial","pageClass":"wide-figures"},"headers":[],"relativePath":"zh/products/codex/dot.md","filePath":"zh/products/codex/dot.md","lastUpdated":1795592559000}'),l={name:"zh/products/codex/dot.md"};function i(h,t,c,g,p,u){const o=r("DocDiagram");return s(),a("div",null,[t[0]||(t[0]=d('<h1 id="dot-chatgpt-里的常驻智能体" tabindex="-1">dot：ChatGPT 里的常驻智能体 <a class="header-anchor" href="#dot-chatgpt-里的常驻智能体" aria-label="Permalink to &quot;dot：ChatGPT 里的常驻智能体&quot;">​</a></h1><blockquote><p>dot 是 ChatGPT 里的<strong>常驻智能体</strong>（always-on agent：你不盯着、它也一直在干活的 AI 助手）。给它一个目标和上下文，它在两次对话之间接着推进；你关掉标签页，它照样在<strong>自己的云电脑</strong>上干活。</p><p>它接的是「长期、多步骤、要跨好几个应用盯进度」的活。本页帮你在 10 分钟内建好 dot 并派出第一个任务，再学会管住它。事实以 OpenAI 帮助中心的 <a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a> 为主，截至 2026-11-24。</p></blockquote><p><strong>写给谁</strong>：会写前端代码，用过 ChatGPT，但没用过 dot，也没接触过「常驻智能体」。</p><p><strong>非目标</strong>：不教 Codex CLI 本身，见 <a href="./codex-cli.html">Codex CLI</a>；不教 ChatGPT Work 本身，见 <a href="./chatgpt-work.html">ChatGPT Work</a>；不写官方页面没出现过的功能。</p><h2 id="学完你能做什么" tabindex="-1">学完你能做什么 <a class="header-anchor" href="#学完你能做什么" aria-label="Permalink to &quot;学完你能做什么&quot;">​</a></h2><ul><li>说清 dot、普通 ChatGPT 对话、Codex 各管什么，并判断一件活该交给谁。</li><li>对照套餐、年龄和地区，确认自己能不能用 dot；找不到入口时知道去哪查。</li><li>创建并命名一个 dot，给它一个写清「目标、资料、何时问我、什么算做完」的任务。</li><li>在活动视图里找到它的任务、文件和等你批准的请求，并给反馈。</li><li>写一条自定义规则，安排一个每天早上的例行检查。</li><li>说清暂停、删除、断开应用各会发生什么，以及哪些事永远要你本人做。</li></ul><h2 id="先确认我能不能用" tabindex="-1">先确认我能不能用 <a class="header-anchor" href="#先确认我能不能用" aria-label="Permalink to &quot;先确认我能不能用&quot;">​</a></h2><h3 id="对照套餐、年龄和地区" tabindex="-1">对照套餐、年龄和地区 <a class="header-anchor" href="#对照套餐、年龄和地区" aria-label="Permalink to &quot;对照套餐、年龄和地区&quot;">​</a></h3><p>截至 2026-11-24，帮助中心列出的范围：</p><table tabindex="0"><thead><tr><th>套餐</th><th>能不能用</th><th>条件与限制</th></tr></thead><tbody><tr><td><strong>Pro</strong></td><td>能</td><td>年满 18 岁；不在欧洲经济区、瑞士、英国</td></tr><tr><td><strong>Plus</strong></td><td>部分账号能</td><td>条件同 Pro；正在逐步放量，没轮到你时客服也开不了，重启应用也没用</td></tr><tr><td><strong>Business Premium</strong></td><td>能</td><td>限 ChatGPT 支持的地区，受工作区资格要求限制；逐步放量</td></tr><tr><td><strong>Business Standard</strong></td><td>美国逐步开放</td><td>切到你的 Business 工作区；看不到创建入口说明还没轮到；有用量限制</td></tr><tr><td><strong>Enterprise / Edu / Healthcare</strong></td><td>普遍可用</td><td>2026-11-18 之前的预览期，要工作区管理员为你的角色开启；自 2026-11-18 起默认可用，除非管理员退出</td></tr><tr><td><strong>Free / Go</strong></td><td>未列入</td><td>帮助中心的可用清单里没有这两个套餐</td></tr></tbody></table><p>三条跨套餐的限制：</p><ul><li><strong>年龄</strong>：未满 18 岁不能用。</li><li><strong>数量</strong>：Business 和 Enterprise 工作区里，每位成员可以创建<strong>一个个人 dot</strong>。发布文说，除首个 dot 外，将来才能添加更多 dot。</li><li><strong>Enterprise 的驻留要求</strong>：数据或推理驻留在阿联酋的工作区不可用。受监管或 Healthcare 工作区先读 <a href="https://help.openai.com/en/articles/20001069-hipaa-eligible-products-and-functionality" target="_blank" rel="noreferrer">HIPAA eligible products and functionality</a>。</li></ul><blockquote><p>官方页面之间还有几处说法对不上，比如 Plus 是否已开放、Enterprise 的驻留与 EKM 资格。本页的表照帮助中心写，差异逐条列在「深入阅读」末尾。</p></blockquote><h3 id="找到入口" tabindex="-1">找到入口 <a class="header-anchor" href="#找到入口" aria-label="Permalink to &quot;找到入口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你在哪里</th><th>怎么找</th></tr></thead><tbody><tr><td>桌面网页</td><td>打开 <a href="https://chatgpt.com/dots" target="_blank" rel="noreferrer">chatgpt.com/dots</a></td></tr><tr><td>手机应用</td><td>已有 dot：打开 <strong>Dot</strong> 标签页；没有这个标签页：从侧边栏打开 <strong>Dots</strong></td></tr><tr><td>企业工作区</td><td>看不到入口就问工作区管理员：你的角色有没有 dots 权限，工作区有没有退出</td></tr></tbody></table><p>找不到时，先确认你登录的是打算用的那个账号和工作区。帮助中心明说：<strong>Plus 与 Business Premium 是逐步放量的</strong>。Plus 还没轮到你的账号时，OpenAI 客服无法替你开通，重启应用也不会改变权限。</p><h3 id="备好设备" tabindex="-1">备好设备 <a class="header-anchor" href="#备好设备" aria-label="Permalink to &quot;备好设备&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要做的事</th><th>用什么</th></tr></thead><tbody><tr><td>创建 dot</td><td>ChatGPT 手机应用（iOS 或 Android，装最新版）、桌面应用（也有 Windows 版）、桌面网页</td></tr><tr><td>给 dot 发消息或通话</td><td>以上三处都行，通话入口是对话里的电话按钮</td></tr><tr><td>手机网页</td><td><strong>不支持</strong></td></tr><tr><td>连接自己的电脑</td><td>只能在<strong>那台电脑上的 ChatGPT 桌面应用</strong>里操作</td></tr><tr><td>连接 Slack</td><td>从桌面端 ChatGPT 连接</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="先记住-dot-是什么、不是什么" tabindex="-1">先记住 dot 是什么、不是什么 <a class="header-anchor" href="#先记住-dot-是什么、不是什么" aria-label="Permalink to &quot;先记住 dot 是什么、不是什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>它是</th><th>它不是</th></tr></thead><tbody><tr><td>ChatGPT 里的一项功能，入口在 ChatGPT 应用内</td><td>不是开源 Codex CLI 的一部分。官方文档没有给出任何终端入口</td></tr><tr><td>一个常驻智能体：有目标、有记忆，在两次对话之间接着干</td><td>不是「一直开着的聊天窗口」。你关掉标签页，它在云电脑上照常干活</td></tr><tr><td>一个会分活的协调者：编码任务转给 Codex，文档类任务转给 ChatGPT Work</td><td>不是写代码的 agent 本身。写代码、看 diff、提 PR 是 Codex 的活</td></tr><tr><td>住在云端，自带一台云电脑和浏览器</td><td>不是你本机上的程序。你的电脑默认和它分开，除非你主动连接</td></tr></tbody></table><p>发布文里的 <strong>specialist dots</strong>（专家型 dot）是另一回事：由公司配置身份和权限、面向组织的试点，本页只讲你个人的 dot。</p><h3 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>术语</th><th>一句话解释</th><th>为什么需要</th></tr></thead><tbody><tr><td><strong>常驻智能体</strong>（always-on agent）</td><td>你不盯着也一直在干活的 AI 助手</td><td>长期的活需要有人在两次对话之间接着推进</td></tr><tr><td><strong>云电脑</strong>（cloud computer）</td><td>在云端、专属于这个 dot 的一台电脑，有自己的文件、软件和浏览器</td><td>你的电脑关机，它也能干活</td></tr><tr><td><strong>已连接的应用 / 插件</strong>（plugins）</td><td>你授权 dot 使用的外部服务，比如邮箱、日历、代码托管</td><td>要它查邮箱、读日历、看代码仓库，先得把这些应用连上</td></tr><tr><td><strong>渠道</strong>（channel）</td><td>你和 dot 说话的地方：ChatGPT、Slack、Teams、短信</td><td>换渠道还是同一个 dot</td></tr><tr><td><strong>handle</strong></td><td>dot 的账号名，默认 <code>@你的用户名-dot</code></td><td>在聊天里点名它</td></tr><tr><td><strong>记忆</strong>（memory）</td><td>ChatGPT 给它的背景，加上它自己记的笔记</td><td>不用每次重新交代偏好和项目背景</td></tr><tr><td><strong>定时任务</strong>（scheduled tasks）</td><td>你安排的提醒或循环检查</td><td>重复的活不用你记得触发</td></tr><tr><td><strong>主动调研</strong>（proactive research）</td><td>你没发新消息时，它在后台只读地翻已连接的信息</td><td>它能主动发现和你手头工作相关的变化</td></tr><tr><td><strong>自定义规则</strong>（Custom rules）</td><td>规定某一类动作它是不问、先问、还是交给你</td><td>默认规则不可能刚好符合你的边界</td></tr><tr><td><strong>pre-approved</strong>（预先批准）</td><td>你在提示里明确要求过这个动作</td><td>「帮我起草」和「帮我发出去」是两回事</td></tr><tr><td><strong>Auto-review</strong>（自动审查）</td><td>动作执行前的一道独立检查</td><td>拦下按错收件人、分享你不想分享的信息这类动作</td></tr><tr><td><strong>活动视图</strong>（Activity View）</td><td>看它正在做什么、做完了什么的面板</td><td>得知道它在干什么，才谈得上管住它</td></tr><tr><td><strong>本机电脑访问</strong>（local computer access）</td><td>允许 dot 用你自己电脑上的文件和工具</td><td>它要动你本地的项目时才需要，默认关闭</td></tr><tr><td><strong>Codex 云环境</strong>（Codex cloud environment）</td><td>在 Codex 里预先配好的可复用编码环境</td><td>dot 跑云端编码任务时拿它当工作台</td></tr><tr><td><strong>接管</strong>（Take over）</td><td>你亲自操作 dot 的电脑，做完再 <strong>Return control</strong>（归还控制权）</td><td>登录、验证码这类步骤要你亲手做</td></tr></tbody></table><h3 id="把几个概念连起来看" tabindex="-1">把几个概念连起来看 <a class="header-anchor" href="#把几个概念连起来看" aria-label="Permalink to &quot;把几个概念连起来看&quot;">​</a></h3><p><strong>云电脑是 dot 自己的。</strong> 它有自己的文件、软件和浏览器会话，能在两次使用之间保留状态。你在自己电脑上登录了某个网站，不等于 dot 也登录了：它的云浏览器有独立的登录会话。</p><p><strong>三种连接各管各的。</strong> 渠道负责和它说话、收它的更新；已连接的应用让它在权限内使用那个服务的信息和工具；本机电脑让它使用那台电脑的文件、应用和任务。连了其中一个，不会顺带连上另外两个。在 Slack 里找得到 dot，不代表它连上了你的邮箱。</p><p><strong>记忆分两层。</strong> dot 从 ChatGPT 的记忆出发，也会自己记笔记，包括从已连接的应用里得到的信息。手机端 <code>Customize &gt; Memory</code>（自定义 &gt; 记忆）显示的是共享的 ChatGPT 记忆设置；dot 自己的笔记是独立的，改那里的设置不一定改得了它已经记下的内容。</p><p><strong>它和 ChatGPT 之间是双向的。</strong> dot 能收到 ChatGPT 的记忆和最近的对话上下文，也能检索你过去的 ChatGPT 对话找相关内容。反过来，你和 dot 的对话也可能进入 ChatGPT 的记忆。</p><p><strong>定时任务是你安排的，主动调研是它自发的。</strong> 你让它每天早上看日历，这是定时任务，按你给的权限执行。你不说话时它翻已连接的信息找线索，这是主动调研，只读。</p><p><strong>内置规则打底，自定义规则加码。</strong> dot 自带一套「什么时候自己动手、什么时候问你」的规则。自定义规则是可选的补充，用来给某类动作定更具体的边界。</p><p><strong>Auto-review 是另一道关。</strong> 动作执行前，一个独立的安全系统拿它对照你的指令、自定义规则和安全要求，决定放行、要你批准，还是交还给你。dot 自己关不掉这道检查。</p><p><strong>活动视图是你的仪表盘。</strong> 在桌面应用里打开 dot 的资料页就能看。每个任务有自己的对话，不会自动带入你在别处和 dot 说过的所有内容。</p><p><strong>暂停是踩刹车，删除是清空。</strong> 暂停可以恢复，不删信息。删除不可撤销，会开始删除 dot 自己保存的记忆。两者各自的后果见下文「暂停和删除」。</p><h2 id="它是怎么工作的" tabindex="-1">它是怎么工作的 <a class="header-anchor" href="#它是怎么工作的" aria-label="Permalink to &quot;它是怎么工作的&quot;">​</a></h2><p>读图前带着一个问题：<strong>我从 Slack 或手机发出去的一句话，经过谁，最后落到哪台电脑、哪个应用上？哪些路默认就通，哪些要我先点头？</strong> 下面的图分三层回答：你接触 dot 的渠道、dot 本身、它能动用的东西。</p>',36)),n(o,{src:"/diagrams/chatgpt-dot-model.svg",alt:"这张图分三层，回答一句话从渠道发出后经过谁、落到哪里，以及哪些路默认就通、哪些要你先授权或先建好。第一层是渠道，从左到右五个：ChatGPT 桌面应用、桌面网页、手机应用、Slack、Teams。第二层是 dot 本身，画成紫色，里面有四样东西：目标、记忆、自定义规则、定时任务。第三层是 dot 能动用的东西，从左到右四个：dot 自己的云电脑与浏览器、已连接的应用与插件、可选的本机电脑、Codex 云环境。渠道和第二层之间，每个渠道都有一对橙色箭头：向下的箭头表示你的消息从这个渠道流向 dot，向上的箭头表示 dot 的进度、提问和需要你拍板的决定流回这个渠道。第二层和第三层之间有四条橙色箭头，每条都从 dot 指向第三层的一项，表示 dot 去动用它。实线表示默认可用：通向 ChatGPT 桌面应用、桌面网页、手机应用这三个渠道的箭头，以及 dot 指向它自己的云电脑与浏览器的箭头都是实线，对应卡片的边框也是实线，状态写的是默认可用或一创建就有。虚线表示需要你显式授权或先建好：通向 Slack 和 Teams 的箭头，以及 dot 指向已连接的应用与插件、本机电脑、Codex 云环境的箭头都是虚线，对应卡片的边框也是虚线；应用和插件要你自己连，本机电脑默认关闭、点了 Allow access 才通，Codex 云环境要先在 Codex 里建好。渠道和第三层之间没有任何直接连线：连了 Slack，不会自动连上你的邮箱或电脑。底部图例：实线是默认可用，虚线是需你显式授权或先建好，橙色箭头是消息与指令的方向；青色是你的渠道，紫色是 dot 本身，翠绿色是 dot 默认就有的云电脑与浏览器，琥珀色是需要你授权或先建好的东西。本图省略了模型训练细节、dot 的内部架构、具体的应用产品（没有画成产品图标），以及 Teams 的设置步骤。",width:920}),t[1]||(t[1]=d(`<blockquote><p><strong>图的依据：</strong> 三层的对象来自帮助中心 <a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a>：dot 有自己的电脑；创建后可以在手机应用、桌面应用里和它对话，手机网页不支持；本机电脑访问是可选的，默认关闭；Codex 云环境要先在 Codex 里建好；应用通过 Plugins 连接。Slack 与 Teams 两个渠道、以及「上下文跨渠道延续」来自发布文 <a href="https://openai.com/index/introducing-dots/" target="_blank" rel="noreferrer">Introducing dots</a>。图中保留了三层的对象、消息与进度的往返方向，以及默认可用和需要你授权的区别；省略了每一项的设置步骤、dot 的内部实现，以及它把任务委派给 ChatGPT Work 或 Codex 的细节。实线是默认就通的路，虚线是需要你显式授权或先建好的路。</p></blockquote><p>图里最该盯住的是两点。</p><p><strong>第一，dot 站在中间。</strong> 渠道只是入口。换渠道不会得到一个新的 dot，也不会重置它的记忆。消息留在各自的渠道里，dot 可以跨渠道使用相关上下文。</p><p><strong>第二，第三层不是默认全开的。</strong> dot 一创建就有云电脑和浏览器。应用和插件要你自己连。本机电脑默认关闭，点了 <strong>Allow access</strong>（允许访问）才通。Codex 云环境要先在 Codex 里建好。渠道和第三层之间没有直接连线：连了 Slack，不会自动连上你的邮箱或电脑。</p><p>企业工作区多一层：管理员可以分别关掉 dot 的云浏览器、代码联网和电脑操作。关掉之后，dot 仍能起草内容、整理信息、使用工作区允许的已连接应用。</p><p>dot 干活时会把一部分工作分出去：用后台 agent 并行处理，开单独的云线程，在已连接的电脑上创建 Work 或 Codex 任务。云线程会作为单独的对话出现在桌面、网页和手机应用里，你可以打开继续指挥。它也能接着做已有的本机 Codex 任务。</p><p>发布文写明 dot 由 GPT‑6 Astra 驱动；2026-11-03 的更新注记说，驱动 dots 的模型家族新增了 GPT‑6.1 Terra。</p><h3 id="对照-dot-的云电脑和「本机当服务器」" tabindex="-1">对照：dot 的云电脑和「本机当服务器」 <a class="header-anchor" href="#对照-dot-的云电脑和「本机当服务器」" aria-label="Permalink to &quot;对照：dot 的云电脑和「本机当服务器」&quot;">​</a></h3><p><a href="./../cindy/">Cindy</a> 是开源的智能体应用，走的是另一条路。它装在你的电脑和手机上，官方 README 的说法是「你的电脑成为你的服务器」。</p><table tabindex="0"><thead><tr><th>对比项</th><th>dot</th><th>Cindy</th></tr></thead><tbody><tr><td>活在哪台电脑上跑</td><td>dot 自己的云电脑，你的电脑关机也能干</td><td>你的电脑；要远程用它，电脑得保持在线</td></tr><tr><td>它是什么</td><td>ChatGPT 里的一项功能，由 OpenAI 托管</td><td>开源客户端，自己下载安装，客户端为 Apache-2.0 许可</td></tr><tr><td>用谁的模型</td><td>OpenAI 的 GPT‑6 模型家族</td><td>你已有的订阅、API 或本地模型；可接 Claude Code、Codex、Pi</td></tr><tr><td>编码任务</td><td>转交给 Codex</td><td>在一个界面里用你已装好的 coding agent</td></tr></tbody></table><p>Cindy 一列来自它的 <a href="https://github.com/makecindy/cindy" target="_blank" rel="noreferrer">GitHub 仓库 README</a>，截至 2026-11-24。</p><h2 id="_10-分钟创建-dot-并派出第一个任务" tabindex="-1">10 分钟创建 dot 并派出第一个任务 <a class="header-anchor" href="#_10-分钟创建-dot-并派出第一个任务" aria-label="Permalink to &quot;10 分钟创建 dot 并派出第一个任务&quot;">​</a></h2><p>这条最短路径不连接你的电脑，任务模板也不让它对外发消息。六步是：确认入口、创建并命名、接一个应用、发任务、看结果、给反馈。</p><h3 id="_1-确认入口" tabindex="-1">1. 确认入口 <a class="header-anchor" href="#_1-确认入口" aria-label="Permalink to &quot;1. 确认入口&quot;">​</a></h3><p>打开 <a href="https://chatgpt.com/dots" target="_blank" rel="noreferrer">chatgpt.com/dots</a>，或手机应用的 <strong>Dot</strong> 标签页。看得到创建入口就继续。看不到就回到上一节查套餐和工作区。</p><h3 id="_2-创建并命名" tabindex="-1">2. 创建并命名 <a class="header-anchor" href="#_2-创建并命名" aria-label="Permalink to &quot;2. 创建并命名&quot;">​</a></h3><ol><li>在手机应用、桌面应用或桌面浏览器里打开 dots，跟着引导走。</li><li>给它起名、选外形。可以先保留默认，以后再改。</li><li>连接插件这一步可以先跳过，下一步再接。</li></ol><p>它会自我介绍，并根据手头的上下文建议自己能帮什么。默认 handle 是 <code>@你的用户名-dot</code>，起名后变成 <code>@你的用户名-你起的名字</code>。以后改名或头像：点它的名字或头像打开资料页，再点铅笔图标。</p><h3 id="_3-接一个应用" tabindex="-1">3. 接一个应用 <a class="header-anchor" href="#_3-接一个应用" aria-label="Permalink to &quot;3. 接一个应用&quot;">​</a></h3><p>手机端打开 dot 的资料页，进 <code>Customize &gt; Plugins</code>（自定义 &gt; 插件）。选一个受支持的应用，<strong>连接前先看它的权限</strong>，再连。桌面端可以在 ChatGPT 的 <strong>Plugins</strong> 标签页里连接和管理。</p><p>这个界面用的是共享的 ChatGPT 设置。你在 ChatGPT、ChatGPT Work、Codex 里连过的应用，dot 可以在你已授权的范围内使用。发布文（2026-09-29）说插件生态能连 4,000 多个应用；帮助中心提醒，对你可用的应用可能不同。</p><h3 id="_4-发出第一个任务" tabindex="-1">4. 发出第一个任务 <a class="header-anchor" href="#_4-发出第一个任务" aria-label="Permalink to &quot;4. 发出第一个任务&quot;">​</a></h3><p>任务里写清四件事：<strong>目标、可用资料、什么时候问你、什么算做完</strong>。下面这段可以照抄，把尖括号里的内容换掉：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要你帮我盯一件事：&lt;项目名&gt; 的依赖更新。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标：告诉我 &lt;某个依赖&gt; 的最新版本改了什么，会不会影响我们。</span></span>
<span class="line"><span>可用资料：&lt;代码仓库链接&gt; 里的 package.json 和更新日志，当前版本我用 + 号附上。</span></span>
<span class="line"><span>什么时候问我：要改代码、开 PR，或在群里发消息之前，先问我。</span></span>
<span class="line"><span>什么算做完：一段话，写清最新版本号、和我们相关的三条变更、影响大不大及理由。</span></span>
<span class="line"><span>先做一版给我看，我确认之后，再谈要不要持续盯着。</span></span></code></pre></div><p>要附文件或照片，在对话里点 <strong>+</strong>。</p><h3 id="_5-在活动视图里看结果" tabindex="-1">5. 在活动视图里看结果 <a class="header-anchor" href="#_5-在活动视图里看结果" aria-label="Permalink to &quot;5. 在活动视图里看结果&quot;">​</a></h3><p>在桌面应用里点 dot 的名字或头像打开资料页，在 <strong>In progress</strong>（进行中）、<strong>Scheduled</strong>（已定时）、<strong>Completed</strong>（已完成）下看活动。打开任务可以看进度、文件和结果。</p><p>想亲眼看它在干什么：从资料页打开它的电脑。要动手操作，点 <strong>Take over</strong>（接管）；用完点 <strong>Return control</strong>（归还控制权），它才能接着干。</p><h3 id="_6-给反馈" tabindex="-1">6. 给反馈 <a class="header-anchor" href="#_6-给反馈" aria-label="Permalink to &quot;6. 给反馈&quot;">​</a></h3><p>直接在对话里回复，补充信息或改方向。结果不对时，打开<strong>出问题的那个任务</strong>，在里面说清楚你要的结果，附上相关文件或链接。</p><h3 id="第一个任务怎么选" tabindex="-1">第一个任务怎么选 <a class="header-anchor" href="#第一个任务怎么选" aria-label="Permalink to &quot;第一个任务怎么选&quot;">​</a></h3><p>从你经常要查看或更新的一件事开始。先交一版给你审，再扩大职责。官方举的三类例子：准备演示文稿、把访谈转成内容、改进一个应用。</p><h2 id="日常用法" tabindex="-1">日常用法 <a class="header-anchor" href="#日常用法" aria-label="Permalink to &quot;日常用法&quot;">​</a></h2><h3 id="写第一条自定义规则" tabindex="-1">写第一条自定义规则 <a class="header-anchor" href="#写第一条自定义规则" aria-label="Permalink to &quot;写第一条自定义规则&quot;">​</a></h3><p>对「分享、购买、访问」这三类动作，你可以给某一类操作定一条规则。</p><ul><li><strong>手机端</strong>（帮助中心）：打开 <code>Customize &gt; Custom rules</code>（自定义 &gt; 自定义规则），查看默认规则或添加一条。</li><li><strong>桌面和网页</strong>（官方文档）：打开 <code>Settings</code> &gt; <code>Personalization</code>，在 <code>Permissions</code> 下选 <code>Custom rules</code>，点 <code>Add</code>。</li></ul><p>描述这条规则覆盖的动作，从下表选一种处理方式。手机端点对勾保存，桌面端点 <code>Add rule</code>。</p><table tabindex="0"><thead><tr><th>处理方式</th><th>含义</th><th>前端工程师的例子</th></tr></thead><tbody><tr><td><strong>Take action without asking</strong>（不问直接做）</td><td>直接做，不请求批准</td><td>把整理好的当日日程摘要发进和你的 ChatGPT 对话</td></tr><tr><td><strong>Take action if pre-approved</strong>（已获预先批准时执行）</td><td>你在提示里明确要求过才做；否则动手前立刻问</td><td>往团队 Slack 频道发周报草稿：只有你在任务里点名让它发，它才发</td></tr><tr><td><strong>Ask before taking action</strong>（执行前询问）</td><td>做之前先要你批准</td><td>开 PR、合并分支之前先问</td></tr><tr><td><strong>Hand off to you</strong>（交由你处理）</td><td>请你自己来做这个动作</td><td>删除共享的项目文件</td></tr></tbody></table><p>「pre-approved」指你在提示里明确要求过这个动作。官方文档把第二种写作 <strong>Take action when you say so</strong>，意思相同。</p><p>四条边界：</p><ul><li>不必每次批准都写规则。先在对话里把要求说清楚，需要长期生效的边界才写成规则。</li><li>规则不授予应用或电脑访问权限，也不覆盖内置安全机制。改密码这类步骤必须你本人完成。</li><li>dot 会犯错，照着你的规则执行时也会。采信结果前先审一遍。</li><li>Enterprise 工作区的自定义规则默认关闭，要管理员打开。工作区禁用时，已保存的规则不生效，你也改不了。</li></ul><h3 id="安排每天早上的例行检查" tabindex="-1">安排每天早上的例行检查 <a class="header-anchor" href="#安排每天早上的例行检查" aria-label="Permalink to &quot;安排每天早上的例行检查&quot;">​</a></h3><p>直接告诉它。固定时间重复的活要写清四点：查什么或更新什么、什么时候跑（含时区和结束日期）、哪些变化值得通知你、结果送到哪里。例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 9 点（北京时间），未来四周，查看我连接的日历和团队的排期频道。</span></span>
<span class="line"><span>有截止日期变了，就更新项目清单。</span></span>
<span class="line"><span>只有在某个截止日期有风险，或者需要我做决定时，才在 ChatGPT 里告诉我。</span></span>
<span class="line"><span>设好后，把你保存的计划复述给我确认。</span></span></code></pre></div><ul><li>运行结果和主动更新会出现在对话里。</li><li>管理入口有两个：在 dot 资料页的 <strong>Recent activity</strong>（近期活动）里点那个任务，或打开 ChatGPT 的 <strong>Scheduled</strong>。这里能看到进行中、已暂停、已完成的任务。</li><li>打开任务可以改重复周期、时间或完成通知。</li><li>让它复述保存了什么。你也可以直接让它列出、修改或取消自己的定时任务。</li></ul><p>两个提醒：</p><ul><li>它还能读写你已有的 ChatGPT Work 定时任务。让它「调整一下排期」时，说清是哪一个。</li><li>某次运行即使标成了「已完成」，也要看一眼结果。</li></ul><h3 id="在-slack-里找它" tabindex="-1">在 Slack 里找它 <a class="header-anchor" href="#在-slack-里找它" aria-label="Permalink to &quot;在 Slack 里找它&quot;">​</a></h3><ol><li>在桌面端 ChatGPT 里打开 dot 的资料页，点 <strong>Add</strong>（添加）连接 Slack。</li><li>给你的 dot 发私信。或者把它加进某个频道，在话题里 @ 它。</li></ol><p>连上以后：</p><ul><li>默认它只回应你。你可以让它也回应别人。</li><li>告诉它哪类消息送到哪。比如日常进度留在 ChatGPT，要你拍板的事发到 Slack。</li><li>想让它盯某个频道，要明说看哪些频道、注意什么、什么时候通知你，并让它确认。<strong>只把它拉进频道，不等于建立了监控。</strong></li></ul><p>两条边界：只有 dot 的主人能指挥它，别人的私信或 @ 不会让它开工。你可以让它回应别人，但那仍然是你下的指令，对方并没有获得指挥权。它在频道里发的消息，频道里的人都看得到。官方安全指南建议只在组织内部成员都在的频道里使用 dot。</p><p>企业工作区还有两道关：管理员打开 dots 和「添加到 Slack 与 Microsoft Teams」的权限；Slack 工作区需要审批的，由 Slack 的管理员批准。之后每位成员自己完成连接。</p><h3 id="从手机看进度并接管" tabindex="-1">从手机看进度并接管 <a class="header-anchor" href="#从手机看进度并接管" aria-label="Permalink to &quot;从手机看进度并接管&quot;">​</a></h3><ol><li>在 ChatGPT 手机应用里打开和 dot 的对话。要看它的电脑，从资料页打开。</li><li>手机端打开时，控制权直接在你手里。桌面端只是打开拿不到控制权，要点 <strong>Take over</strong> 才能用它的鼠标和键盘。</li><li>用完点 <strong>Return control</strong>，它才能继续。</li></ol><p>通话：打开 dot 的对话，点电话按钮；桌面应用里也可以在资料页点 <strong>Call</strong>。通话时可以打字，挂断后交给它的活可以继续。发布时 dot 不能主动给你打电话。</p><p>短信是另一条渠道，但开放范围两个官方页写得不一样：帮助中心写的是美国、加拿大、墨西哥的部分 Pro 用户，官方文档写的是只向美国的 Pro 用户开放。两边都要求 iMessage 或 RCS。帮助中心还写明，Business 和 Enterprise 工作区不支持短信。设置入口是资料页的 <strong>Texting</strong>；看不到这一项，说明还没轮到你的账号。</p><p>手机网页不支持 dot，要用手机应用。想换一个渠道接着聊，直接换：还是同一个 dot。</p><h3 id="连接本机电脑-让它在你的项目里开-codex-任务" tabindex="-1">连接本机电脑，让它在你的项目里开 Codex 任务 <a class="header-anchor" href="#连接本机电脑-让它在你的项目里开-codex-任务" aria-label="Permalink to &quot;连接本机电脑，让它在你的项目里开 Codex 任务&quot;">​</a></h3><p>先看风险，再决定连不连。</p><ul><li><strong>授权是长期的，而且跨渠道生效。</strong> 确认 <strong>Allow access</strong> 后，无论你从哪个渠道和 dot 说话，它都能访问那台电脑上的文件、在上面干活。连接在任务之间一直保留。</li><li><strong>活在本机跑，协调在云端。</strong> 对话、工具结果和任务上下文不会只留在那台电脑上。</li><li><strong>它能在上面开任务、用工具。</strong> 连接后它可以创建 Work 或 Codex 任务、使用本地技能，并在云浏览器被挡住时改用你的本地浏览器。</li><li><strong>和 Codex 的连接是两回事。</strong> 把电脑连到 Codex 或开启 Work Sync，都不会让 dot 获得本机访问权限。反过来也一样。</li><li><strong>离线不等于断开。</strong> <strong>Offline</strong>（离线）只表示电脑暂不可用，授权还在。要收回必须点 <strong>Revoke access</strong>（撤销访问权限）。</li><li><strong>用摄像头、麦克风或屏幕还要系统权限。</strong> 前提是电脑已连接，并且你在设备设置里允许了 ChatGPT 应用使用它们。</li></ul><p>决定要连，就在<strong>那台电脑上</strong>操作：</p><ol><li>打开 ChatGPT 桌面应用，进入 dot 的资料页。</li><li>在 <code>Computers</code>（电脑）下找到 <strong>Your computer</strong>（你的电脑），点 <strong>Allow access</strong>。</li><li>阅读确认提示，再点一次 <strong>Allow access</strong>。</li></ol><p>那台电脑要保持在线、开着 ChatGPT 应用，dot 才能用它。本机上的工作会作为独立任务出现在侧边栏里。官方企业管理文档另要求桌面应用为 26.929 或更高版本。</p><p>连好后可以这样交代：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在我的电脑上，为 &lt;项目目录&gt; 开一个 Codex 任务：&lt;要改什么&gt;。</span></span>
<span class="line"><span>做完给我看 diff 和测试输出。不要合并，也不要推送。</span></span></code></pre></div><p>查看或收回：资料页的 <code>Computers</code> 下能看到已连接的电脑，点 <strong>Revoke access</strong> 收回。</p><h3 id="让它用-codex-云环境" tabindex="-1">让它用 Codex 云环境 <a class="header-anchor" href="#让它用-codex-云环境" aria-label="Permalink to &quot;让它用 Codex 云环境&quot;">​</a></h3><p>你的电脑不开机，dot 也能跑编码任务，前提是<strong>先在 Codex 里把环境建好</strong>。</p><ol><li>在 Codex 里创建并发布一个环境。官方文档给的入口有两个：新任务里选 <code>Work in</code> &gt; <code>Cloud</code>，打开 <code>Select environment</code>，选 <code>Create environment</code>；或从 <code>Settings</code> &gt; <code>Codex Cloud</code> &gt; <code>Environments</code> 进入。建完要点 <strong>Publish</strong>。背景见 <a href="./codex-cloud.html">Codex Cloud</a>。</li><li>回到和 dot 的对话，让它在这个环境里创建任务。说清用哪个环境、改什么。</li><li>在活动视图里打开任务看结果。</li></ol><p>环境里要有这个仓库和它的配置。官方的要求是：先在 Codex 里建好，再去找 dot。</p><p>两条限制：云环境不支持电脑操作和浏览器操作；你本机的个人技能不会同步到云环境。</p><h3 id="暂停和删除-各自会发生什么" tabindex="-1">暂停和删除，各自会发生什么 <a class="header-anchor" href="#暂停和删除-各自会发生什么" aria-label="Permalink to &quot;暂停和删除，各自会发生什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>暂停</th><th>删除</th></tr></thead><tbody><tr><td>怎么做</td><td>资料页的更多选项菜单 <code>•••</code> 里选 <strong>Pause</strong>；恢复时点 <strong>Paused • Tap to resume</strong>（已暂停，轻点以恢复）</td><td><code>•••</code> 里选 <strong>Delete</strong>，再点一次 <strong>Delete</strong> 确认，或点 <strong>Cancel</strong> 保留</td></tr><tr><td>对 dot 本身</td><td>停下它当前的主任务，随时可恢复</td><td>结束对这个 dot 的访问</td></tr><tr><td>它自己的记忆</td><td>保留</td><td>开始删除</td></tr><tr><td>主对话</td><td>保留</td><td>被归档，不能再用这个 dot 继续</td></tr><tr><td>它创建的独立 Work / Codex 对话</td><td>可能继续运行</td><td>保留</td></tr><tr><td>独立安排的定时任务</td><td>可能继续运行</td><td>先自己检查，不想要的先停掉</td></tr><tr><td>能不能撤销</td><td>可以恢复</td><td><strong>不可撤销</strong></td></tr><tr><td>之后</td><td>点一下就恢复</td><td>不会自动生成替代品。删除完成后可以新建，但新 dot 不恢复原来的上下文</td></tr></tbody></table><p>操作前记住三件事：</p><ul><li><strong>暂停不等于全停。</strong> 委派出去的任务到活动视图里停，循环任务到 <strong>Scheduled</strong> 里停。</li><li><strong>删除前把要用的东西存下来。</strong> 工作区所有者也能通过工作区管理删除一个个人 dot。</li><li><strong>恢复不了时先找人。</strong> dot 被工作区管理员暂停了，要请管理员解除。你的 dots 权限被收回了，要先请工作区所有者或管理员恢复。</li></ul><h2 id="分清-dot-和-codex-的分工" tabindex="-1">分清 dot 和 Codex 的分工 <a class="header-anchor" href="#分清-dot-和-codex-的分工" aria-label="Permalink to &quot;分清 dot 和 Codex 的分工&quot;">​</a></h2><p>官方文档给四种体验的定位：</p><table tabindex="0"><thead><tr><th>体验</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>要一个回答、一段解释、一些点子，或在对话里起草</td></tr><tr><td><strong>ChatGPT Work</strong></td><td>有一件要委托的事：调研、分析、做一份文件。现在做，或按计划做</td></tr><tr><td><strong>Codex</strong></td><td>要构建、调试、测试、评审软件，直接和代码、开发工具打交道</td></tr><tr><td><strong>你的 dot</strong></td><td>要一个 agent 长期跟进一项职责：情况变了它自己想下一步，在对话之间接着推进。它在 ChatGPT 或 Slack 里向你汇报，并把任务委托给 ChatGPT Work 或 Codex</td></tr></tbody></table><p>一句话：<strong>dot 负责「长期盯着、跨应用推进」，Codex 负责「写代码」。</strong> dot 把编码任务交给 Codex，有本机和云端两条路：</p><table tabindex="0"><thead><tr><th>任务类型</th><th>dot 怎么处理</th><th>前提</th></tr></thead><tbody><tr><td>新的本机 Work 或 Codex 任务</td><td>在已连接的电脑上创建</td><td>那台电脑在线，ChatGPT 应用开着</td></tr><tr><td>已有的本机 Codex 任务</td><td>在已连接的电脑上接着做</td><td>你告诉它是哪个任务、想改什么</td></tr><tr><td>新的云端编码任务</td><td>在你已建好的 Codex 云环境里创建</td><td>你的电脑可以离线</td></tr><tr><td>dot 自己建的任务</td><td>它检查结果、发后续指令</td><td>用任务原来所在的电脑或云环境</td></tr></tbody></table><p>换了 dot 使用的电脑，已有的任务不会跟着搬家。</p><h3 id="何时用-dot-何时直接用-codex" tabindex="-1">何时用 dot，何时直接用 Codex <a class="header-anchor" href="#何时用-dot-何时直接用-codex" aria-label="Permalink to &quot;何时用 dot，何时直接用 Codex&quot;">​</a></h3><table tabindex="0"><thead><tr><th>你的情况</th><th>用谁</th><th>理由</th></tr></thead><tbody><tr><td>对着当前文件改一个函数，边看 diff 边调</td><td><a href="./codex-cli.html">Codex CLI</a> 或 IDE 扩展</td><td>小改动留在本地更快</td></tr><tr><td>一个改动要并行试几次，或你不在开发机旁</td><td><a href="./codex-cloud.html">Codex Cloud</a></td><td>托管环境可并行，不占本机</td></tr><tr><td>手机上接着批一台已连接电脑上的任务</td><td><a href="./codex-remote.html">Codex Remote</a></td><td>你逐步指挥那条会话</td></tr><tr><td>一件事要盯好几天：新 issue 进来就排查、备好修复、等评审</td><td>dot</td><td>它在对话之间接着推进，编码部分转给 Codex</td></tr><tr><td>活跨好几个应用：Slack 收反馈、GitHub 看 issue、文档里更新记录</td><td>dot</td><td>它跨应用协调，再按类型委托出去</td></tr></tbody></table><h2 id="计费与用量" tabindex="-1">计费与用量 <a class="header-anchor" href="#计费与用量" aria-label="Permalink to &quot;计费与用量&quot;">​</a></h2><p>本页不写价格数字。下表只转述官方原话，具体金额以 <a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a> 为准。</p><table tabindex="0"><thead><tr><th>项目</th><th>官方怎么说</th><th>出处</th></tr></thead><tbody><tr><td>首个 dot</td><td>Pro 或 Business Premium 套餐已包含，不额外收费。套餐还包含一定额度的「深度工作」，发布后首月额度放宽。将来可以添加更多 dot</td><td>发布文，2026-09-29</td></tr><tr><td>和 dot 的对话</td><td>不计入 ChatGPT 用量限制</td><td>发布文；官方文档 Meet dots</td></tr><tr><td>dot 转交给 Codex 或 ChatGPT Work 的任务</td><td>照常计入对应产品的用量限制，并出现在它们的用量报表里</td><td>发布文；官方文档 Manage dots permissions and capabilities</td></tr><tr><td>Enterprise：预览期</td><td>预览免费。2027-01-13 之前 Enterprise dot 不收费</td><td>官方文档；帮助中心</td></tr><tr><td>Enterprise：开始计费</td><td>自 2027-01-14 起，对所有已启用的 dot 开始计费</td><td>帮助中心</td></tr><tr><td>Enterprise：委派出去的任务</td><td>dot 委托给 ChatGPT Work 或 Codex 线程的工作，按标准费率另行计费</td><td>帮助中心</td></tr><tr><td>Business Standard</td><td>有用量限制</td><td>帮助中心</td></tr></tbody></table><p>三个容易算错的地方：</p><ul><li><strong>「dot 对话不占额度」不等于「全免费」。</strong> 它替你开的 Codex 或 Work 任务照常扣对应产品的额度。</li><li><strong>「已启用」指不处于暂停状态的 dot。</strong> 官方文档 Manage dots permissions and capabilities 写明：管理员暂停期间停止计费，恢复到活跃状态后继续。</li><li><strong>ChatGPT Work 和 Codex 共用定价、积分和用量限制</strong>（Pricing 页）。dot 委派出去的任务落在这套共享额度里。</li></ul><p>Enterprise 的更多定价信息，帮助中心让你联系 OpenAI 的客户代表。</p><h2 id="安全边界-它能自己做什么、不能做什么" tabindex="-1">安全边界：它能自己做什么、不能做什么 <a class="header-anchor" href="#安全边界-它能自己做什么、不能做什么" aria-label="Permalink to &quot;安全边界：它能自己做什么、不能做什么&quot;">​</a></h2><h3 id="你不发消息时-它能做什么" tabindex="-1">你不发消息时，它能做什么 <a class="header-anchor" href="#你不发消息时-它能做什么" aria-label="Permalink to &quot;你不发消息时，它能做什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不等你发新消息，它能</th><th>它不能</th></tr></thead><tbody><tr><td>在后台调研，然后建议自己能帮什么</td><td>给别人发消息</td></tr><tr><td>主动查看已连接的信息，并据此形成记忆</td><td>通过插件修改内容</td></tr><tr><td>运行你安排好的提醒或循环任务</td><td>控制浏览器或电脑</td></tr></tbody></table><p>右列的限制只针对主动调研。调研完的后续动作，必须照常走权限和审查。你安排的定时任务按你给的权限执行，和主动调研是两回事。</p><p>你可以在 dot 的资料页里查看定时任务，也可以在不想它继续时暂停它。Enterprise 管理员无法单独关闭主动调研。</p><h3 id="五个「不等于」" tabindex="-1">五个「不等于」 <a class="header-anchor" href="#五个「不等于」" aria-label="Permalink to &quot;五个「不等于」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>容易以为</th><th>实际上</th><th>怎么办</th></tr></thead><tbody><tr><td>断开应用，数据就收回了</td><td>断开只阻止新的访问。dot 已经拿到的信息还在它自己的上下文里</td><td>要删它自己的记忆，只能删除 dot</td></tr><tr><td>暂停了，活就全停了</td><td>暂停不删信息，也不停掉所有的活。独立的 Work / Codex 任务和独立安排的定时任务可能继续</td><td>到活动视图和 <strong>Scheduled</strong> 里分别检查、分别停</td></tr><tr><td>写了规则，就等于给了权限</td><td>自定义规则不授予应用或电脑访问权限，也不覆盖内置安全机制</td><td>权限在 Plugins 和 <code>Computers</code> 里单独给</td></tr><tr><td>我登录了，dot 也就登录了</td><td>它的云浏览器有独立的登录会话</td><td>完成它发来的登录请求，或接管后自己登录，再归还控制权</td></tr><tr><td>短信是端到端加密的</td><td>第三方 Linq 在消息到达 OpenAI 之前处理短信，不是端到端加密，用 iMessage 或 RCS 也一样</td><td>敏感内容别走短信</td></tr></tbody></table><h3 id="哪些事永远要你本人做" tabindex="-1">哪些事永远要你本人做 <a class="header-anchor" href="#哪些事永远要你本人做" aria-label="Permalink to &quot;哪些事永远要你本人做&quot;">​</a></h3><ul><li><strong>改密码、在金融账户之间转账。</strong> dot 可以帮着做周边的事，但这些步骤必须交还给你。</li><li><strong>每次都要你确认的动作。</strong> 永久删除数据、安装或运行来源不明的软件、授予新的安全敏感权限。</li><li><strong>验证码和安全验证。</strong> 它可能需要你提供验证码，或者接管过去自己完成。</li></ul><h3 id="还要知道的边界" tabindex="-1">还要知道的边界 <a class="header-anchor" href="#还要知道的边界" aria-label="Permalink to &quot;还要知道的边界&quot;">​</a></h3><ul><li><strong>只有你能指挥你的 dot。</strong> 别人的私信或 @ 不会让它开工。它在频道里发的消息，频道里的人都看得到。</li><li><strong>批准有范围。</strong> 批准一条消息，不等于允许它以后一直替你联系别人。</li><li><strong>花钱要你点头。</strong> 它可以用你在商家网站保存的卡下单，但需要你批准。用 Wallet 结账时，每笔付款都要你用生物识别确认。</li><li><strong>审查不是万无一失。</strong> dot 会犯错。官方自己写明，Auto-review 对浏览器、桌面和委派动作的覆盖仍在评估中。</li><li><strong>网页、邮件、文档里可能藏着恶意指令。</strong> 这叫 prompt injection。dot 被训练成区分你的指令和它读到的内容，但这些防护只降低风险，不能消除风险。</li><li><strong>它和 ChatGPT 共享记忆，且删不掉单条。</strong> dot 能收到 ChatGPT 的记忆和最近的对话上下文，也能检索你过去的 ChatGPT 对话。你目前不能查看、删除或修改单条 dot 记忆。关掉 ChatGPT 的 Memory 只停止共享，不删除它已经收到的信息。</li><li><strong>撤回不保证成功。</strong> 已经完成的动作能不能撤销，取决于动作和应用。删除 dot 也不会撤销它在已连接应用里做过的改动，或收回已经送达的消息。</li><li><strong>数据用途由设置决定。</strong> Business、Enterprise、Edu 工作区默认不拿你的内容训练模型。个人套餐看「Improve the model for everyone」这个设置。OpenAI 不会直接拿主动调研和 dot 给自己的笔记训练模型。</li><li><strong>本机访问有收尾时间。</strong> 管理员关掉本机访问后，已经授权的本地任务可能还在跑完。</li><li><strong>建议开多因素认证（MFA）。</strong> 入口在 <code>Settings &gt; Security and login</code>。</li></ul><p>受监管或 Healthcare 工作区另有一层：隐私与安全 FAQ 说 dots 在满足条件时属于 HIPAA eligible，但同一家帮助中心的 HIPAA 文章把「Use Codex in the cloud」列在不覆盖的清单里。让 dot 转交 Codex 云环境任务之前，先和管理员确认。</p><h2 id="避开这些坑" tabindex="-1">避开这些坑 <a class="header-anchor" href="#避开这些坑" aria-label="Permalink to &quot;避开这些坑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>原因</th><th>解决</th></tr></thead><tbody><tr><td>dot 用不了我的电脑或本地工具</td><td>没在<strong>那台电脑上的桌面应用</strong>里点 <strong>Allow access</strong>；电脑离线或没开应用；以为把电脑连到 Codex 或开了 Work Sync 就等于连给了 dot</td><td>在那台电脑上：资料页 <code>Computers</code> &gt; <code>Your computer</code> &gt; <strong>Allow access</strong>，确认后再点一次。保持在线、开着应用</td></tr><tr><td>dot 用不了某个应用或网站</td><td>插件没装或连错账号；只有读权限；连接过期；云浏览器的登录态和你的浏览器是分开的；网站屏蔽云浏览器</td><td>检查插件和账号，看它被允许做什么；连接过期就重连；完成登录请求，或接管登录后归还控制权。网站屏蔽时，可让它改用已连接的电脑</td></tr><tr><td>我批准了，操作还是被拦</td><td>任务里还有单独的登录、连接或批准请求没处理；规则要求你明确下令；「要一份草稿」不等于授权发送</td><td>打开任务处理待办请求；直接明说要它执行这个动作。自定义规则不授权，也不覆盖安全机制</td></tr><tr><td>找不到 dot 的工作成果或文件</td><td>任务在另一台电脑或云环境里；换了 dot 使用的电脑，旧任务不会搬过来</td><td>资料页里打开任务看进度、文件和结果。本地任务在已连接电脑的侧边栏，循环任务在 <code>Scheduled</code></td></tr><tr><td>dot 停了，或漏了指令</td><td>它在等你的决定、批准、登录或连接；它被暂停了；纠正发在了别的对话里</td><td>打开出问题的任务处理待办；被暂停就恢复；在那个任务里纠正，并附上文件或链接</td></tr><tr><td>找不到 dot</td><td>账号或工作区不对；套餐还没放量到你的账号</td><td>确认账号和工作区，打开 <code>chatgpt.com/dots</code>；手机上看 <code>Dot</code> 标签页或侧边栏的 <code>Dots</code></td></tr><tr><td>和 dot 通话有问题</td><td>帮助中心没写原因</td><td>打开和 dot 的对话，点电话按钮。通话不行就用打字继续</td></tr><tr><td>改了 Memory 设置，dot 好像还是记得</td><td>dot 自己的笔记独立于 ChatGPT 的记忆设置</td><td>关掉共享不会删它已收到的信息。要删只能删除 dot</td></tr><tr><td>从 Pro 换成 Plus 后 dot 没了</td><td>帮助中心原文：从 Pro 改订 Plus，会失去对 dot 的访问</td><td>降级前先把要留的成果另存。恢复订阅后是否还原，官方没说</td></tr><tr><td>手机浏览器里找不到入口</td><td>手机网页不支持 dot</td><td>装最新版手机应用，或改用桌面应用、桌面网页</td></tr><tr><td>暂停了，活还在跑</td><td>暂停只停 dot 当前的主任务。委派出去的 Work / Codex 任务和独立安排的定时任务可能继续</td><td>到活动视图和 <code>Scheduled</code> 里逐个检查、逐个停</td></tr><tr><td>断开了插件，以为数据收回了</td><td>断开只阻止新的访问，dot 已经拿到的信息还在</td><td>要清掉它自己的记忆，只能删除 dot</td></tr><tr><td>把它拉进 Slack 频道，它却不盯着</td><td>只加进频道不会建立监控</td><td>明说看哪些频道、注意什么、何时通知，并让它确认</td></tr><tr><td>在 Slack 里找得到它，它却说连不上我的邮箱或电脑</td><td>渠道、应用、本机电脑是三种独立连接</td><td>分别连接：应用走 Plugins，电脑走 <code>Computers</code></td></tr></tbody></table><h2 id="按官方步骤逐项排错" tabindex="-1">按官方步骤逐项排错 <a class="header-anchor" href="#按官方步骤逐项排错" aria-label="Permalink to &quot;按官方步骤逐项排错&quot;">​</a></h2><p>帮助中心的排错小节共八条。上一节给了原因，这里给能照着点的步骤。</p><h3 id="dot-用不了我的电脑或本地工具" tabindex="-1">dot 用不了我的电脑或本地工具 <a class="header-anchor" href="#dot-用不了我的电脑或本地工具" aria-label="Permalink to &quot;dot 用不了我的电脑或本地工具&quot;">​</a></h3><ol><li>在你希望 dot 使用的那台电脑上，打开 ChatGPT 桌面应用里的 dot 资料页。</li><li>在 <code>Computers</code> 下找到 <code>Your computer</code>，点 <strong>Allow access</strong>。</li><li>阅读确认提示，再点一次 <strong>Allow access</strong>。</li></ol><p>保持那台电脑在线、开着 ChatGPT 应用。<code>Offline</code> 只表示电脑不可用，不表示连接被撤销。<code>Allow access</code> 点不了，确认你是在那台电脑上用桌面应用。</p><h3 id="dot-用不了某个应用或网站" tabindex="-1">dot 用不了某个应用或网站 <a class="header-anchor" href="#dot-用不了某个应用或网站" aria-label="Permalink to &quot;dot 用不了某个应用或网站&quot;">​</a></h3><ol><li>已连接的应用：确认装了受支持的插件，而且连的是正确的账号。</li><li>看它被允许的动作。能读信息，不一定能改信息或发消息。</li><li>连接过期了，打开重连请求重新连接。</li><li>需要登录的网站：完成 dot 发来的登录请求，包括网站要求的验证。或者接管，自己登录，完成后归还控制权。</li><li>网站屏蔽云浏览器：让 dot 改试你已连接的电脑。这可能另开一个本地任务，不会带上云浏览器的会话，也不保证网站就能用。</li></ol><h3 id="我批准了-操作还是被拦" tabindex="-1">我批准了，操作还是被拦 <a class="header-anchor" href="#我批准了-操作还是被拦" aria-label="Permalink to &quot;我批准了，操作还是被拦&quot;">​</a></h3><ol><li>打开出问题的任务，看有没有单独的登录、连接或批准请求。</li><li>看相关的自定义规则。如果它要求你明确下令，就直接要求 dot 执行这个动作。</li><li>记住两条：自定义规则不授予应用或电脑访问权限，也不覆盖内置安全机制。有些步骤（比如改密码）必须你本人完成。</li></ol><h3 id="找不到-dot-的工作成果或文件" tabindex="-1">找不到 dot 的工作成果或文件 <a class="header-anchor" href="#找不到-dot-的工作成果或文件" aria-label="Permalink to &quot;找不到 dot 的工作成果或文件&quot;">​</a></h3><ol><li>在桌面应用里点 dot 的名字或头像，打开资料页，再打开相关任务。</li><li>本地任务在已连接电脑的侧边栏里。循环执行的工作在 <code>Scheduled</code> 下。</li><li>回到任务最初所在的电脑或云环境找。换了 dot 使用的电脑，已有任务不会搬过去。</li><li>要看它的云电脑，去资料页的 <code>Computers</code> 下。要亲自操作就点 <strong>Take over</strong>，完事点 <strong>Return control</strong>。</li></ol><h3 id="dot-停了-或漏了指令" tabindex="-1">dot 停了，或漏了指令 <a class="header-anchor" href="#dot-停了-或漏了指令" aria-label="Permalink to &quot;dot 停了，或漏了指令&quot;">​</a></h3><ol><li>打开出问题的任务，处理所有等你决定、批准、登录或连接的请求。</li><li>是你暂停的，就恢复它。是管理员暂停或收回了权限，就去找管理员。</li><li>循环执行的工作：打开 <code>Scheduled</code>，核对保存的指令和时间。即使标成完成，也要看结果。</li><li>纠正要发在出问题的那个任务里，写明你要的结果，附上文件或链接。</li><li>要报 bug、提反馈，在和 dot 的主对话里说。它也可能主动建议你提交反馈。</li></ol><h3 id="找不到-dot" tabindex="-1">找不到 dot <a class="header-anchor" href="#找不到-dot" aria-label="Permalink to &quot;找不到 dot&quot;">​</a></h3><p>确认用的是正确的账号和工作区，再打开 <code>chatgpt.com/dots</code>。按套餐对号：</p><ul><li><strong>Plus</strong>：支持地区内向部分账号逐步开放。</li><li><strong>Pro</strong>：欧洲经济区、瑞士、英国以外，年满 18 岁的用户可用。</li><li><strong>Business Premium</strong>：ChatGPT 支持的地区可用，受工作区资格要求限制。</li><li><strong>Business Standard</strong>：切到你的 Business 工作区。还看不到创建入口，说明可能还在向你放量。手机上用最新版应用。</li><li><strong>Enterprise，含 Edu 和 Healthcare</strong>：问工作区管理员，你的角色有没有开 dots。</li></ul><h3 id="和-dot-通话有问题" tabindex="-1">和 dot 通话有问题 <a class="header-anchor" href="#和-dot-通话有问题" aria-label="Permalink to &quot;和 dot 通话有问题&quot;">​</a></h3><p>打开和 dot 的对话，点电话按钮。通话不好用但聊天可用，就在对话里打字继续。</p><h3 id="改了-memory-设置或删除-dot-会变什么" tabindex="-1">改了 Memory 设置或删除 dot，会变什么 <a class="header-anchor" href="#改了-memory-设置或删除-dot-会变什么" aria-label="Permalink to &quot;改了 Memory 设置或删除 dot，会变什么&quot;">​</a></h3><ul><li>手机端 <code>Customize &gt; Memory</code> 显示的是共享的 ChatGPT 记忆设置。dot 自己保存的记忆是独立的，改那里不一定会改它已经记下的笔记。</li><li>删除 dot 会结束对它的访问，并开始删除它自己保存的记忆。先存好要用的结果，看清删除提示再确认。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>dot 会把编码任务交给 Codex：读 <a href="./codex-cli.html">Codex CLI</a>，学会在终端里用它。</li><li>想知道 dot 委托出去的文档类任务长什么样：读 <a href="./chatgpt-work.html">ChatGPT Work</a>。</li><li>要让 dot 用云环境跑代码：读 <a href="./codex-cloud.html">Codex Cloud</a>。</li><li>想比较「手机遥控自己的电脑」和「活跑在云端」：读 <a href="./codex-remote.html">Codex Remote</a>。</li><li>概念记混了：查 <a href="./codex-glossary.html">Codex 术语表</a>。整体路线看 <a href="./">Codex 生态学习导航</a>。</li></ol><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><ul><li><a href="https://help.openai.com/en/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">Getting started with your dot</a>：本页的主事实源，排错小节最全。有<a href="https://help.openai.com/zh-hans-cn/articles/20001530-getting-started-with-your-dot" target="_blank" rel="noreferrer">中文版</a>，但内容比英文版旧。</li><li><a href="https://openai.com/index/introducing-dots/" target="_blank" rel="noreferrer">Introducing dots</a>：OpenAI 发布文，2026-09-29 发布，文内有 2026-11-03 的更新注记。讲定位、安全设计和计费原则。有<a href="https://openai.com/zh-Hans-CN/index/introducing-dots/" target="_blank" rel="noreferrer">中文版</a>。</li><li><a href="https://openai.com/index/how-we-build-safety-security-and-privacy-into-dots/" target="_blank" rel="noreferrer">How we build safety, security, and privacy into dots</a>：OpenAI 安全博客。讲动作规则、安全登录和主动调研的限制是怎么实现的。</li><li><a href="https://help.openai.com/en/articles/20001529-dots-privacy-security-and-safety-faqs" target="_blank" rel="noreferrer">Dots privacy, security, and safety FAQs</a>：权限、记忆、删除和数据用途的问答。</li><li><a href="https://learn.chatgpt.com/docs/dots" target="_blank" rel="noreferrer">Meet dots</a>：官方文档的总览页。五篇子页分别讲<a href="https://learn.chatgpt.com/docs/dots/getting-started" target="_blank" rel="noreferrer">上手</a>、<a href="https://learn.chatgpt.com/docs/dots/channels" target="_blank" rel="noreferrer">发消息的渠道</a>、<a href="https://learn.chatgpt.com/docs/dots/tasks-and-memory" target="_blank" rel="noreferrer">任务与记忆</a>、<a href="https://learn.chatgpt.com/docs/dots/computers-and-apps" target="_blank" rel="noreferrer">连接电脑与应用</a>、<a href="https://learn.chatgpt.com/docs/dots/controls" target="_blank" rel="noreferrer">控制你的 dot</a>。</li><li><a href="https://help.openai.com/en/articles/20001554-manage-dots-in-chatgpt-workspaces" target="_blank" rel="noreferrer">Manage dots in ChatGPT workspaces</a>：写给管理员，讲工作区能控制哪些权限。</li><li><a href="https://learn.chatgpt.com/docs/enterprise/dots-admin-guide" target="_blank" rel="noreferrer">Manage dots permissions and capabilities</a> 和 <a href="https://learn.chatgpt.com/docs/enterprise/dots-security" target="_blank" rel="noreferrer">Safety and security in dots</a>：写给管理员，讲启用、审计、离职处理和数据保留。</li><li><a href="https://learn.chatgpt.com/docs/environments/cloud-environments" target="_blank" rel="noreferrer">Cloud environments</a>：Codex 云环境怎么建。</li><li><a href="https://learn.chatgpt.com/docs/sandboxing/auto-review" target="_blank" rel="noreferrer">Auto-review</a>：Codex 侧自动审查的工作方式，帮你理解 dot 里的那道检查。</li><li><a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">ChatGPT Release Notes</a>：带日期的 dots 更新，比如手机创建、短信、Wallet。</li><li><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a>：ChatGPT Work 与 Codex 共用的套餐和用量规则。</li></ul><h3 id="官方页面之间说法不一致的地方" tabindex="-1">官方页面之间说法不一致的地方 <a class="header-anchor" href="#官方页面之间说法不一致的地方" aria-label="Permalink to &quot;官方页面之间说法不一致的地方&quot;">​</a></h3><p>两个官方页说法不同时，本页两处都写，不替你裁决。下表截至 2026-11-24。</p><table tabindex="0"><thead><tr><th>事项</th><th>说法 A</th><th>说法 B</th></tr></thead><tbody><tr><td>Plus 与 Business Standard 能不能用</td><td>帮助中心：Plus 向部分账号放量，Business Standard 在美国逐步开放</td><td>官方文档 Meet dots 只列 Pro、Business Premium、Enterprise / Edu / Healthcare。ChatGPT Release Notes 2026-11-19 写「Dots are currently available to Pro users」</td></tr><tr><td>在哪里创建</td><td>帮助中心：手机应用、桌面应用、桌面网页都行</td><td>发布文（2026-09-29）：先在桌面应用或桌面浏览器创建，之后才能用手机应用发消息。官方 What&#39;s new 记录 2026-10-05 至 10-09 那一周才加入手机创建</td></tr><tr><td>Teams 渠道</td><td>发布文：可以在 Slack 和 Teams 里给 dot 发消息。管理员文章有「Add dots to Slack and Microsoft Teams」权限</td><td>帮助中心与官方文档只给了 Slack 的设置步骤</td></tr><tr><td>短信开放范围</td><td>帮助中心：美国、加拿大、墨西哥的部分 Pro 用户</td><td>官方文档 Message your dot 与 What&#39;s new（2026-10-28）：只向美国的 Pro 用户开放</td></tr><tr><td>自定义规则的入口和第二种行为的名字</td><td>帮助中心：手机端 <code>Customize &gt; Custom rules</code>，行为叫 <strong>Take action if pre-approved</strong></td><td>官方文档 Control your dot：桌面和网页在 <code>Settings</code> &gt; <code>Personalization</code>，行为叫 <strong>Take action when you say so</strong></td></tr><tr><td>连接电脑的第一下按钮</td><td>帮助中心：<code>Computers</code> 下找到 <code>Your computer</code>，点 <strong>Allow access</strong></td><td>官方文档：先点 <strong>Allow</strong>，再确认 <strong>Allow access</strong></td></tr><tr><td>「删除」叫什么、删掉什么</td><td>帮助中心英文版叫 <strong>Delete</strong>，并提醒你自己检查、停掉不想要的定时任务</td><td>帮助中心中文版和官方安全文档叫「重置 / Reset」，写明会删除对话、记忆和定时任务</td></tr><tr><td>Enterprise 的驻留与 EKM 资格</td><td>帮助中心：只有阿联酋的数据或推理驻留工作区不可用</td><td>Local computer access 一页写预览期不支持数据驻留、EKM 与 FedRAMP 工作区不可用。Safety and security in dots 写支持数据驻留，EKM 面向合格工作区支持，FedRAMP 不可用</td></tr><tr><td>Enterprise 何时默认可用</td><td>帮助中心与官方文档：2026-11-18 起默认可用，除非管理员退出</td><td>Safety and security in dots 把 2026-11-04 称为 GA date</td></tr><tr><td>dots 是否符合 HIPAA</td><td>隐私与安全 FAQ：在合格工作区、有 BAA 且对你的角色启用时，属于 HIPAA eligible</td><td>HIPAA 文章的「覆盖」与「不覆盖」两张清单都没列 dots</td></tr><tr><td>dot 有没有独立邮箱</td><td>帮助中心：发布时不能给 dot 单独的邮箱地址</td><td>隐私与安全 FAQ 提到，dot 有自己的邮箱或 Slack 账号时，仍能用你已连接的插件</td></tr><tr><td>Enterprise 怎么计费</td><td>帮助中心：按工作类型的固定费率</td><td>官方文档 Manage dots permissions and capabilities：固定费率或按用量付费</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">Codex 生态学习导航</a>：Codex 家族的学习地图</li><li><a href="./codex-cli.html">Codex CLI</a>、<a href="./chatgpt-work.html">ChatGPT Work</a>、<a href="./codex-cloud.html">Codex Cloud</a>、<a href="./codex-remote.html">Codex Remote</a></li><li><a href="./../t3code/">T3 Code</a>：开源的 coding agent 控制台，让你本机上已装好的 agent 进同一个界面</li><li><a href="./../cindy/">Cindy</a>：开源智能体应用，你的电脑当服务器</li><li><a href="./../tailscale/">Tailscale</a>：Codex 云环境连内网服务时，官方目前支持的 VPN 提供方</li><li><a href="./../uu-remote/">UU 远程</a>：网易的远程控制软件，从手机直接操作另一台电脑</li></ul>`,133))])}const k=e(l,[["render",i]]);export{P as __pageData,k as default};
